const DEFAULT_AVATAR='https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=180&q=80';
const VIPS=[{level:0,name:'عادي',cost:0,color:'#94a3b8',perk:'الميزات الأساسية'},{level:1,name:'VIP 1',cost:1000,color:'#67e8f9',perk:'إطار دخول خفيف وشارة مميزة'},{level:2,name:'VIP 2',cost:2000,color:'#a5b4fc',perk:'إطار متوهج وشعار دخول أفخم'},{level:3,name:'VIP 3',cost:3000,color:'#d8b4fe',perk:'مؤثرات دخول وشارة ملكية'},{level:4,name:'VIP 4',cost:4000,color:'#f9a8d4',perk:'إطار أسطوري وحضور بارز في الغرف'},{level:5,name:'VIP 5',cost:5000,color:'#f7c948',perk:'فخامة كاملة ودعم مباشر وصلاحيات موسعة'}];
let sessionUser=null,profile=null;
const db=()=>window.supabaseClient;
const fmt=n=>Number(n||0).toLocaleString('ar-EG');
const vip=n=>VIPS.find(v=>v.level===Number(n))||VIPS[0];
function toast(msg){const t=document.createElement('div');t.className='toast';t.textContent=msg;(document.getElementById('toast-root')||document.body).appendChild(t);setTimeout(()=>t.remove(),2800);}
async function getProfile(id=sessionUser?.id){const {data,error}=await db().from('profiles').select('id,username,email,display_name,avatar_url,membership_type,coins,vip_level,gender,role,status,suspended_until,suspension_type').eq('id',id).maybeSingle();if(error)throw error;return data;}
async function ensureProfile(user,name,gender){let p=await getProfile(user.id);if(!p){const payload={id:user.id,username:name||user.email.split('@')[0],display_name:name||user.email.split('@')[0],email:user.email,coins:0,vip_level:0,membership_type:'عادي (Standard)',avatar_url:DEFAULT_AVATAR,gender:gender||user.user_metadata?.gender||null,role:'user',status:'active'};const {data,error}=await db().from('profiles').insert(payload).select('id,username,email,display_name,avatar_url,membership_type,coins,vip_level,gender,role,status').single();if(error)throw error;p=data;}return p;}
async function requireAuth(){const {data,error}=await db().auth.getUser();if(error||!data.user){location.href='index.html';return false;}sessionUser=data.user;profile=await ensureProfile(sessionUser);if(profile.status==='suspended'&&profile.suspended_until&&new Date(profile.suspended_until)>new Date()){await db().auth.signOut();alert('هذا الحساب موقوف مؤقتًا حتى '+new Date(profile.suspended_until).toLocaleString('ar-EG'));location.href='index.html';return false;}if(profile.status==='suspended'&&(!profile.suspended_until||new Date(profile.suspended_until)<=new Date())){await db().from('profiles').update({status:'active',suspended_until:null,suspension_type:null}).eq('id',sessionUser.id);profile.status='active';}if(profile.status==='banned'){await db().auth.signOut();alert('هذا الحساب مغلق نهائيًا.');location.href='index.html';return false;}return true;}
async function signIn(email,password){const {error}=await db().auth.signInWithPassword({email,password});if(error)throw error;location.href='app.html#home';}
async function signUp(name,email,password,gender){const {data,error}=await db().auth.signUp({email,password,options:{data:{full_name:name,gender}}});if(error)throw error;if(data.user){sessionUser=data.user;await ensureProfile(data.user,name,gender);}location.href='app.html#home';}
async function logout(){await db().auth.signOut();location.href='index.html';}
function header(){const dev=profile.role==='developer'?'<a href="app.html#developer" class="btn small gold" title="لوحة المطور"><i class="fa-solid fa-shield-halved"></i> المطور</a>':'';return `<header class="top-header"><a class="balance" href="app.html#profile"><i class="fa-solid fa-coins"></i><b>${fmt(profile.coins)}</b><small>كوينز</small></a><a class="brand" href="app.html#home"><span class="brand-mark">♛</span><b>WEBCHAT</b></a><div class="head-actions">${dev}<a href="app.html#notifications" class="icon-btn"><i class="fa-solid fa-bell"></i><i class="dot"></i></a><a href="app.html#profile" class="avatar-mini"><img src="${profile.avatar_url||DEFAULT_AVATAR}"></a></div></header>`;}
function nav(active){return `<nav class="bottom-nav">${[['home','house','الرئيسية'],['top','trophy','التوب'],['search','magnifying-glass','البحث'],['notifications','bell','الإشعارات'],['vip','gem','VIP'],['profile','user','حسابي']].map(a=>`<a class="nav-item ${active===a[0]?'active':''}" href="app.html#${a[0]}"><i class="fa-solid fa-${a[1]}"></i><span>${a[2]}</span></a>`).join('')}</nav>`;}
function page(title,active,body){return `<div class="page-shell">${header()}<main class="page-content">${body}</main>${nav(active)}<div id="toast-root"></div></div>`;}
function roomCard(r){return `<div class="room-card"><div class="room-cover">${r.cover_emoji||'✨'}<span class="live-dot">● ${r.is_open?'مفتوحة الآن':'مغلقة'}</span></div><h3>${escapeHtml(r.name)}</h3><p><i class="fa-solid fa-users"></i> ${r.member_count||0} عضو <span>${r.room_type==='game'?(r.game_type||'لعبة'):'دردشة كتابية'}</span></p><button class="btn small ${r.room_type==='game'?'gold':'ghost'}" onclick="joinRoom('${r.id}')">انضم للغرفة</button></div>`;}
function escapeHtml(s=''){return s.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
async function getRooms(type){let q=db().from('rooms').select('id,owner_id,name,room_type,game_type,bet_amount,cover_emoji,is_open,created_at').eq('is_open',true).order('created_at',{ascending:false}).limit(30);if(type)q=q.eq('room_type',type);const {data,error}=await q;if(error)throw error;return Promise.all((data||[]).map(async r=>{const {count}=await db().from('room_members').select('user_id',{count:'exact',head:true}).eq('room_id',r.id);return {...r,member_count:count||0};}));}
async function home(){const rooms=await getRooms();return page('الرئيسية','home',`<section class="hero"><div><span class="eyebrow">منصة اجتماعية للألعاب والتجمع</span><h1>أهلاً بك يا <em>${escapeHtml(profile.display_name||profile.username)}</em></h1><p>اكتشف غرفًا حقيقية للدردشة الكتابية، نافس أصدقاءك، واصنع حضورك الملكي.</p><div class="hero-actions"><a class="btn gold" href="app.html#games"><i class="fa-solid fa-gamepad"></i> اكتشف الألعاب</a><a class="btn ghost" href="app.html#gathering"><i class="fa-solid fa-users"></i> التجمع الممتع</a></div></div><div class="hero-orb"><span>VIP ${profile.vip_level||0}</span><strong>♛</strong><small>${vip(profile.vip_level).perk}</small></div></section><div class="section-head"><div><span class="eyebrow">مساحاتك المفضلة</span><h2>اختر عالمك</h2></div><a href="app.html#search">استكشف الكل <i class="fa-solid fa-arrow-left"></i></a></div><div class="feature-grid"><a class="feature-card games" href="app.html#games"><i class="fa-solid fa-dice"></i><h3>الألعاب</h3><p>لودو، 7 و70، وروليت</p><b>ابدأ اللعب <i class="fa-solid fa-arrow-left"></i></b></a><a class="feature-card rooms" href="app.html#gathering"><i class="fa-solid fa-microphone-lines"></i><h3>التجمع الممتع</h3><p>غرف قروبات ومحادثات كتابية</p><b>انضم الآن <i class="fa-solid fa-arrow-left"></i></b></a><a class="feature-card code" href="app.html#programming"><i class="fa-solid fa-code"></i><h3>البرمجة</h3><p>مساحة الشروحات قادمة</p><b>قريبًا <i class="fa-solid fa-arrow-left"></i></b></a></div><section class="rooms-strip"><div class="section-head"><div><span class="eyebrow">من قاعدة البيانات</span><h2>الغرف المفتوحة</h2></div><a href="app.html#gathering">عرض الكل</a></div><div class="room-row">${rooms.map(roomCard).join('')||'<p class="empty">لا توجد غرف مفتوحة بعد.</p>'}</div></section>`);}
const GAME_CARDS=[['Ludo','🎲','Ludo Royale','4 لاعبين','لودو أونلاين مع مطابقة حقيقية.'],['77','⚖️','الأحكام 77','لاعبان','جلسة تنافسية سريعة.'],['Roulette','🎡','Royal Roulette','حتى 6 لاعبين','اختيار عشوائي للاعبين المنتظرين.'],['Ben 10','🦸','Ben 10 Arena','أونلاين','تحديات واحد ضد واحد.'],['Race','🏎️','Royal Race','سباق','سباق جماعي سريع.'],['Jump','🪂','Jump Masters','قفز','تحدي قفز أونلاين.'],['Treasure Hunt','💎','Treasure Hunt','استكشاف','مطاردة كنز جماعية.'],['Speed Cards','🃏','Speed Cards','ذكاء سريع','مباراة بطاقات قصيرة.'],['Memory Match','🧠','Memory Match','ذاكرة','تطابق بطاقات مع لاعبين.']];
function openGameLobby(game){const item=GAME_CARDS.find(x=>x[0]===game)||['','🎮',game,'أونلاين',''];const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<div class="match-modal panel"><div class="panel-head"><div><span class="eyebrow">بدء ${escapeHtml(item[2])}</span><h2>${item[1]} اختر الرهان</h2></div><button class="icon-btn" onclick="this.closest('.modal-backdrop').remove()">×</button></div><p class="empty">حدد قيمة الرهان ثم اضغط موافق للدخول إلى قائمة الانتظار.</p><div class="bet-options">${[100,200,300,400,500].map(v=>`<button class="bet-option" data-bet="${v}" onclick="this.parentElement.querySelectorAll('.bet-option').forEach(x=>x.classList.remove('selected'));this.classList.add('selected')">${v}<small>كوينز</small></button>`).join('')}</div><button class="btn gold full" onclick="confirmGameBet('${game}')">موافق · بدء المطابقة</button></div>`;document.body.appendChild(modal);modal.querySelector('.bet-option')?.click();}
function confirmGameBet(game){const bet=Number(document.querySelector('.bet-option.selected')?.dataset.bet||100);document.querySelector('.modal-backdrop')?.remove();queueForGame(game,bet);}
function startRobotMatch(game,bet){const box=document.getElementById('match-status');if(!box)return;box.innerHTML=`<div class="robot-match"><span class="robot-icon">🤖</span><h2>مباراة ضد Robot</h2><p>الروبوت قوي، واحتمال فوزك في هذه المباراة <b>30%</b>.</p><button class="btn gold" onclick="confirmRobotMatch('${game}',${bet})">موافق · العب مع Robot</button></div>`;}
async function confirmRobotMatch(game,bet){const {error}=await db().rpc('start_robot_match',{p_game:game,p_bet:Number(bet)});if(error)return toast(error.message.includes('insufficient_coins')?'رصيدك لا يكفي لدفع الرهان':'تعذر بدء المباراة: '+error.message);profile.coins=Number(profile.coins)-Number(bet);location.hash=`robot/${encodeURIComponent(game)}/${bet}`;}
const INTEGRATED_GAMES=[
 ['ludo.html','🎲','لودو الملكية الفاخرة','لودو تفاعلية بكانفاس، نرد، أحجار وحركة خطوة بخطوة.','4 لاعبين'],
 ['ahkam.html','🏛️','مجلس الأحكام الملكي','قرعة ملكية، أحكام، روبوتات ذكية ومؤثرات صوتية.','روبوتات'],
 ['domino.html','🀄','دومينو الشيش','دومينو رباعي أو ثنائي مع بوتات وسحب القطع.','2 أو 4 لاعبين'],
 ['roulette.html','🎡','عجلة الحظ الملكية','عجلة مرئية، صور متعددة، رقائق ومضاعفات مختلفة.','حظ ومضاعفات'],
 ['race.html','🏎️','سباق السيارات','قيادة باللمس، تسارع، منافسون، تصادم وصوت محرك.','سباق حي'],
 ['fishing.html','🌊','صائد الأسماك','تصويب باللمس، أسماك متحركة، طلقات ومكافآت.','تصويب ومكافآت']
];
async function games(){return page('الألعاب','home',`<div class="page-title"><span class="eyebrow">الألعاب المدمجة من الحزمة الجديدة</span><h1>قاعة الألعاب</h1><p>تم استبدال الألعاب السابقة بالألعاب التي رفعتها. افتح أي لعبة لتشغيل نسختها التفاعلية الأصلية داخل الموقع.</p></div><div class="game-grid integrated-games">${INTEGRATED_GAMES.map((g,i)=>`<a class="game-card integrated-game-card ${i===0||i===2?'featured':''}" href="games/${g[0]}"><div class="game-icon">${g[1]}</div><span class="pill">${g[4]}</span><h2>${g[2]}</h2><p>${g[3]}</p><span class="btn ${i===0||i===2?'gold':'ghost'} full">فتح اللعبة <i class="fa-solid fa-arrow-left"></i></span></a>`).join('')}</div>`);}
async function roomPage(id){const {data:room,error}=await db().from('rooms').select('id,name,room_type,game_type,is_open,owner_id').eq('id',id).single();if(error||!room)return page('الغرفة','gathering',`<div class="panel"><h2>الغرفة غير موجودة</h2><p class="empty">ربما أُغلقت الغرفة أو لا تملك صلاحية الوصول.</p></div>`);const [{data:messages},{data:members},{data:catalog}]=await Promise.all([db().from('messages').select('id,sender_id,body,message_type,created_at').eq('room_id',id).order('created_at',{ascending:true}).limit(100),db().from('room_members').select('user_id').eq('room_id',id).limit(50),db().from('gift_catalog').select('id,name,emoji,price').eq('active',true).order('created_at',{ascending:false}).limit(20)]);const ids=(members||[]).map(m=>m.user_id);const {data:people}=ids.length?await db().from('profiles').select('id,display_name,username,avatar_url,vip_level').in('id',ids):{data:[]};const personById=Object.fromEntries((people||[]).map(p=>[p.id,p]));return page(room.name,'home',`<div class="page-title"><span class="eyebrow">${room.room_type==='gathering'?'تجمع كتابي':'غرفة لعبة'}</span><h1>${escapeHtml(room.name)}</h1><p>هذه الغرفة مخصصة للمحادثات الكتابية فقط. يمكنك إرسال رسائل وهدايا للأعضاء.</p><button class="btn ghost" onclick="location.hash='gathering'"><i class="fa-solid fa-arrow-right"></i> العودة للغرف</button></div><div class="profile-grid"><div class="panel"><div class="panel-head"><h2>المحادثة الكتابية</h2><span class="status">${messages?.length||0} رسالة</span></div><div id="room-messages" style="height:360px;overflow:auto;background:#0b1018;border-radius:14px;padding:12px">${(messages||[]).map(m=>`<div class="${m.message_type==='vip_entry'?'vip-entry-message':''}" style="padding:9px 0;border-bottom:1px solid #ffffff0b"><b style="color:${m.sender_id===sessionUser.id?'var(--gold)':'var(--cyan)'}">${escapeHtml(personById[m.sender_id]?.display_name||personById[m.sender_id]?.username||'مستخدم')} ${personById[m.sender_id]?.vip_level?`<span class="vip-entry-badge vip-${personById[m.sender_id].vip_level}">VIP ${personById[m.sender_id].vip_level}</span>`:''}</b><small style="color:var(--muted);margin-right:8px">${new Date(m.created_at).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'})}</small><p style="margin:4px 0;color:${m.message_type==='system'?'var(--gold)':'var(--text)'}">${escapeHtml(m.body)}</p></div>`).join('')||'<p class="empty">ابدأ أول رسالة في الغرفة.</p>'}</div><div style="display:flex;gap:8px;margin-top:12px"><input id="room-message-input" placeholder="اكتب رسالة..." style="flex:1;padding:12px;border-radius:10px;border:1px solid var(--line);background:#0b1018;color:var(--text)"><button class="btn gold" onclick="sendRoomMessage('${id}')">إرسال</button></div></div><div class="panel"><div class="panel-head"><h2>أعضاء الغرفة</h2><span>${people?.length||0}</span></div>${(people||[]).map(p=>`<div class="user-result"><img class="vip-avatar vip-${p.vip_level||0}" src="${p.avatar_url||DEFAULT_AVATAR}"><div><b>${escapeHtml(p.display_name||p.username)}</b><small>ID #${p.id.slice(0,8)}</small></div>${p.id!==sessionUser.id?`<button class="btn small ghost" onclick="sendGift('${id}','${p.id}',document.getElementById('gift-select')?.value)">🎁 هدية</button>`:''}</div>`).join('')||'<p class="empty">لا يوجد أعضاء بعد.</p>'}</div><div class="panel" style="margin-top:15px"><div class="panel-head"><h2>الهدايا المتاحة</h2><span>${catalog?.length||0}</span></div>${catalog?.length?`<select id="gift-select" style="width:100%;padding:12px;border-radius:10px;border:1px solid var(--line);background:#0b1018;color:var(--text)">${catalog.map(g=>`<option value="${g.id}">${g.emoji} ${escapeHtml(g.name)} — ${fmt(g.price)} كوينز</option>`).join('')}</select>`:'<p class="empty">لم يضف المطور هدايا بعد.</p>'}</div></div>`);}
async function showGiftPicker(roomId){const [{data:gifts},{data:members}]=await Promise.all([db().from('gift_catalog').select('id,name,emoji,price,image_url').eq('active',true).order('price',{ascending:true}).limit(50),db().from('room_members').select('user_id').eq('room_id',roomId).neq('user_id',sessionUser.id).limit(100)]);const ids=(members||[]).map(x=>x.user_id);const {data:people}=ids.length?await db().from('profiles').select('id,display_name,username').in('id',ids):{data:[]};const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<div class="gift-modal panel"><div class="panel-head"><h2>إرسال هدية</h2><button class="icon-btn" onclick="this.closest('.modal-backdrop').remove()">×</button></div><label>المستلم</label><select id="gift-recipient">${(people||[]).map(x=>`<option value="${x.id}">${escapeHtml(x.display_name||x.username)}</option>`).join('')||'<option value="">لا يوجد أعضاء آخرون</option>'}</select><label>الهدية</label><select id="gift-choice">${(gifts||[]).map(g=>`<option value="${g.id}">${escapeHtml(g.emoji||'🎁')} ${escapeHtml(g.name)} · ${g.price} كوينز</option>`).join('')||'<option value="">لا توجد هدايا متاحة</option>'}</select><button class="btn gold full" onclick="sendRoomGift('${roomId}')">إرسال الهدية</button></div>`;document.body.appendChild(modal);}
async function sendRoomGift(roomId){const receiver=document.getElementById('gift-recipient')?.value,gift=document.getElementById('gift-choice')?.value;if(!receiver||!gift)return toast('اختر المستلم والهدية');const {error}=await db().rpc('send_room_gift',{p_room:roomId,p_receiver:receiver,p_gift:gift});toast(error?'تعذر إرسال الهدية: '+error.message:'تم إرسال الهدية وخصم قيمتها من رصيدك');document.querySelector('.modal-backdrop')?.remove();if(!error)render();}
let activeVoiceRecorder=null,activeVoiceChunks=[];
async function toggleVoiceRecorder(roomId){if(activeVoiceRecorder){activeVoiceRecorder.stop();return toast('جارٍ تجهيز الرسالة الصوتية');}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});activeVoiceChunks=[];activeVoiceRecorder=new MediaRecorder(stream);activeVoiceRecorder.ondataavailable=e=>{if(e.data.size)activeVoiceChunks.push(e.data)};activeVoiceRecorder.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());const blob=new Blob(activeVoiceChunks,{type:activeVoiceRecorder.mimeType||'audio/webm'});activeVoiceRecorder=null;const path=`${sessionUser.id}/${roomId}-${Date.now()}.webm`;const up=await db().storage.from('voice-messages').upload(path,blob,{contentType:blob.type,upsert:false});if(up.error)return toast('تعذر رفع الرسالة الصوتية: '+up.error.message);const {data:url}=db().storage.from('voice-messages').getPublicUrl(path);const {error}=await db().from('messages').insert({room_id:roomId,sender_id:sessionUser.id,body:url.publicUrl,message_type:'audio'});toast(error?'تعذر حفظ الرسالة الصوتية: '+error.message:'تم إرسال الرسالة الصوتية');if(!error)render();};activeVoiceRecorder.start();toast('بدأ التسجيل، اضغط الزر مرة أخرى للإيقاف');}catch(e){toast('تعذر استخدام الميكروفون: '+e.message);}}
function roomMessageContent(m){return m.message_type==='audio'?`<audio controls preload="metadata" src="${m.body}"></audio>`:escapeHtml(m.body||'');}
async function leaveRoom(roomId){const {error}=await db().rpc('leave_room',{p_room:roomId});toast(error?'تعذر مغادرة الغرفة: '+error.message:'تمت مغادرة الغرفة');if(!error)location.hash='gathering';}
async function sendRoomMessage(roomId){const input=document.getElementById('room-message-input'),body=input?.value.trim();if(!body)return;const {error}=await db().from('messages').insert({room_id:roomId,sender_id:sessionUser.id,body,message_type:'text'});if(error)toast('تعذر إرسال الرسالة: '+error.message);else{input.value='';render();}}
function showGiftAnimation(emoji,name,image){const old=document.querySelector('.gift-flight');if(old)old.remove();const el=document.createElement('div');el.className='gift-flight';el.innerHTML=`<div class="gift-burst">${image?`<img src="${image}">`:emoji||'🎁'}</div><b>${escapeHtml(name)}</b><span class="spark s1">✦</span><span class="spark s2">✧</span><span class="spark s3">✺</span>`;document.body.appendChild(el);setTimeout(()=>el.remove(),2600);}
async function sendGift(roomId,receiverId,giftId){if(!giftId)return toast('اختر هدية أولاً');const {data:g}=await db().from('gift_catalog').select('id,name,emoji,image_url,price').eq('id',giftId).eq('active',true).maybeSingle();if(!g)return toast('الهدية غير متاحة حالياً');const {error}=await db().from('user_gifts').insert({sender_id:sessionUser.id,receiver_id:receiverId,gift_catalog_id:g.id,gift_name:g.name,gift_image_url:g.image_url||'https://cdn-icons-png.flaticon.com/512/4213/4213958.png',gift_price:g.price});if(error)toast('تعذر إرسال الهدية: '+error.message);else{await db().from('messages').insert({room_id:roomId,sender_id:sessionUser.id,body:`${g.emoji} أرسل ${g.name} بقيمة ${fmt(g.price)} كوينز`,message_type:'gift'});toast('تم إرسال الهدية وحفظها في حساب المستلم');render();setTimeout(()=>showGiftAnimation(g.emoji,g.name,g.image_url),80);}}
async function gathering(){const rooms=await getRooms('gathering');return page('التجمع الممتع','home',`<div class="page-title"><span class="eyebrow">مجتمعك في مكان واحد</span><h1>التجمع الممتع</h1><p>أنشئ غرفًا حقيقية وتظهر فورًا للمستخدمين الآخرين.</p><div class="inline-actions"><button class="btn gold" onclick="createGathering()"><i class="fa-solid fa-plus"></i> إنشاء غرفة</button></div></div><div class="rooms-list">${rooms.map(roomCard).join('')||'<p class="empty">لا توجد غرف تجمع مفتوحة حاليًا.</p>'}</div>`);}
function vipArt(level){return ''; }
function openConversation(id){window.pendingDeveloperMessage='';location.hash='dm/'+id;}
async function conversationPage(id){const {data:person,error}=await db().from('profiles').select('id,username,display_name,avatar_url,vip_level').eq('id',id).single();if(error||!person)return page('المحادثة','notifications',`<div class="panel"><h2>الحساب غير موجود</h2></div>`);const {data:msgs}=await db().from('messages').select('id,sender_id,recipient_id,body,created_at').or(`and(sender_id.eq.${id},recipient_id.eq.${sessionUser.id}),and(sender_id.eq.${sessionUser.id},recipient_id.eq.${id})`).order('created_at',{ascending:true}).limit(100);return page('المحادثة','notifications',`<div class="page-title"><button class="btn ghost" onclick="location.hash='notifications'">العودة للإشعارات</button><div class="conversation-user"><img class="vip-avatar vip-${person.vip_level||0}" src="${person.avatar_url||DEFAULT_AVATAR}"><div><span class="vip-label animated-vip-name vip-${person.vip_level||0}">${vip(person.vip_level).name}</span><h1>${escapeHtml(person.display_name||person.username)}</h1><p>@${escapeHtml(person.username)}</p></div></div></div><div class="panel conversation-panel"><div id="conversation-messages" class="conversation-messages">${(msgs||[]).map(m=>`<div class="bubble ${m.sender_id===sessionUser.id?'mine':'theirs'}"><span>${escapeHtml(m.body)}</span><small>${new Date(m.created_at).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'})}</small></div>`).join('')||'<p class="empty">ابدأ المحادثة الآن.</p>'}</div><div class="conversation-compose"><input id="direct-message-input" placeholder="اكتب رسالة..." value="${escapeHtml(window.pendingDeveloperMessage||'')}"><button class="btn gold" onclick="sendDirectMessage('${id}')">إرسال</button></div></div>`);}
async function showSocialList(userId,kind){const labels={followers:'المتابعون',following:'يتابعهم',visitors:'الزوار'};let rows=[];if(kind==='followers'){const {data}=await db().from('follows').select('follower_id').eq('following_id',userId).limit(100);rows=(data||[]).map(x=>x.follower_id);}else if(kind==='following'){const {data}=await db().from('follows').select('following_id').eq('follower_id',userId).limit(100);rows=(data||[]).map(x=>x.following_id);}else{const {data}=await db().from('profile_visits').select('visitor_id').eq('profile_id',userId).order('last_seen_at',{ascending:false}).limit(100);rows=(data||[]).map(x=>x.visitor_id);}const {data:people}=rows.length?await db().from('profiles').select('id,display_name,username,avatar_url,vip_level').in('id',rows):{data:[]};const modal=document.createElement('div');modal.className='social-modal-backdrop';modal.innerHTML=`<div class="social-modal"><button class="modal-close" onclick="this.closest('.social-modal-backdrop').remove()">×</button><h2>${labels[kind]}</h2><div class="social-list">${(people||[]).map(x=>`<div class="social-row" onclick="this.closest('.social-modal-backdrop').remove();openUserProfile('${x.id}')"><img class="vip-avatar vip-${x.vip_level||0}" src="${x.avatar_url||DEFAULT_AVATAR}"><div><b>${escapeHtml(x.display_name||x.username)}</b><small>@${escapeHtml(x.username)} · VIP ${x.vip_level||0}</small></div><i class="fa-solid fa-chevron-left"></i></div>`).join('')||'<p class="empty">لا توجد حسابات بعد.</p>'}</div></div>`;document.body.appendChild(modal);}
async function userPage(id){const {data:person,error}=await db().from('profiles').select('id,username,email,display_name,avatar_url,vip_level,coins,gender').eq('id',id).single();if(error||!person)return page('المستخدم','search',`<div class="panel"><h2>المستخدم غير موجود</h2></div>`);if(id!==sessionUser.id)await db().from('profile_visits').upsert({profile_id:id,visitor_id:sessionUser.id,last_seen_at:new Date().toISOString()},{onConflict:'profile_id,visitor_id'});const [gRes,mRes,follow,follower,following,visitors]=await Promise.all([db().from('user_gifts').select('id,gift_name,gift_image_url,sender_id,created_at').eq('receiver_id',id).order('created_at',{ascending:false}).limit(30),db().from('messages').select('id,sender_id,recipient_id,body,created_at').or(`and(sender_id.eq.${id},recipient_id.eq.${sessionUser.id}),and(sender_id.eq.${sessionUser.id},recipient_id.eq.${id})`).order('created_at',{ascending:true}).limit(100),db().from('follows').select('id').eq('follower_id',sessionUser.id).eq('following_id',id).maybeSingle(),db().from('follows').select('id',{count:'exact',head:true}).eq('following_id',id),db().from('follows').select('id',{count:'exact',head:true}).eq('follower_id',id),db().from('profile_visits').select('id',{count:'exact',head:true}).eq('profile_id',id)]);const gifts=gRes.data||[],msgs=mRes.data||[];const senderIds=[...new Set(gifts.map(g=>g.sender_id).filter(Boolean))];const {data:senders}=senderIds.length?await db().from('profiles').select('id,display_name,username').in('id',senderIds):{data:[]};const senderNames=Object.fromEntries((senders||[]).map(x=>[x.id,x.display_name||x.username]));const level=Number(person.vip_level||0);const moderationTools=profile.role==='developer'&&window.moderationTarget===id?`<button class="btn danger" onclick="devBanFromProfile('${id}')">حظر</button>`:'';const {data:rel}=await db().from('relationships').select('id,user_a,user_b').or(`user_a.eq.${id},user_b.eq.${id}`).maybeSingle();const partnerId=rel?(rel.user_a===id?rel.user_b:rel.user_a):null;const {data:partner}=partnerId?await db().from('profiles').select('id,display_name,username,avatar_url,vip_level').eq('id',partnerId).single():{data:null};const relationBlock=partner?`<div class="relationship-banner"><span class="relation-link">♡</span><div><b>مرتبطان</b><small>علاقة موثقة بين الحسابين</small></div><div class="relation-pair"><img class="vip-avatar vip-${person.vip_level||0}" src="${person.avatar_url||DEFAULT_AVATAR}"><strong>${escapeHtml(person.display_name||person.username)}</strong><span>♡</span><img class="vip-avatar vip-${partner.vip_level||0}" src="${partner.avatar_url||DEFAULT_AVATAR}"><strong>${escapeHtml(partner.display_name||partner.username)}</strong></div></div>`:`<div class="relationship-banner pending"><span class="relation-link">♡</span><div><b>طلب علاقة</b><small>تُخصم 500 كوينز من كل طرف عند الموافقة</small></div><button class="btn small gold" onclick="requestRelationship('${id}')">إرسال الطلب</button></div>`;return page('ملف المستخدم','search',`<section class="profile-hero vip-profile vip-${level}" style="--vip-art:url('${vipArt(level)}')"><div class="vip-art-layer"></div><div class="vip-hero-image"></div><div class="vip-wings"><i></i><i></i></div><div class="profile-avatar-wrap"><img src="${person.avatar_url||DEFAULT_AVATAR}" class="profile-avatar vip-${level}"></div><div class="profile-identity"><span class="vip-label animated-vip-name vip-${level}">${vip(level).name}</span><h1 class="animated-vip-name vip-${level}">${escapeHtml(person.display_name||person.username)}</h1><p>@${escapeHtml(person.username)} · ID #${person.id.slice(0,8)} <button class="copy-id" onclick="event.stopPropagation();copyId('${person.id}')">نسخ ID</button></p></div><span style="display:flex;gap:7px"><button class="btn gold" onclick="followUser('${id}')">${follow.data?'متابَع':'متابعة'}</button><button class="btn danger" onclick="reportUser('${id}')">إبلاغ</button></span>${moderationTools}</section>${relationBlock}<div class="stats social-stats"><button onclick="showSocialList('${id}','followers')"><b>${follower.count||0}</b><span>المتابعون</span></button><button onclick="showSocialList('${id}','following')"><b>${following.count||0}</b><span>يتابعهم</span></button><button onclick="showSocialList('${id}','visitors')"><b>${visitors.count||0}</b><span>الزوار</span></button><div><b>VIP ${level}</b><span>المستوى</span></div></div><div class="profile-grid"><div class="panel"><div class="panel-head"><h2>الرسائل الخاصة</h2><span class="status">${msgs.length}</span></div><div style="max-height:300px;overflow:auto">${msgs.map(m=>`<div style="padding:9px;border-bottom:1px solid #ffffff0b"><b style="color:${m.sender_id===sessionUser.id?'var(--gold)':'var(--cyan)'}">${m.sender_id===sessionUser.id?'أنت':escapeHtml(person.display_name||person.username)}</b><p style="margin:4px 0">${escapeHtml(m.body)}</p></div>`).join('')||'<p class="empty">لا توجد رسائل بعد.</p>'}</div><div style="display:flex;gap:8px;margin-top:12px"><input id="direct-message-input" placeholder="اكتب رسالة خاصة..." style="flex:1;padding:12px;border-radius:10px;border:1px solid var(--line);background:#0b1018;color:var(--text)"><button class="btn gold" onclick="sendDirectMessage('${id}')">إرسال</button></div></div><div class="panel gifts"><div class="panel-head"><h2>الهدايا المستلمة</h2><span>${gifts.length}</span></div><div class="gift-grid">${gifts.map(g=>`<div><b>🎁</b><small>${escapeHtml(g.gift_name)}</small><small>من: ${escapeHtml(senderNames[g.sender_id]||'مستخدم')}</small></div>`).join('')||'<p class="empty">لا توجد هدايا بعد.</p>'}</div></div></div>`);}
async function sendDirectMessage(recipientId){const input=document.getElementById('direct-message-input'),body=input?.value.trim();if(!body)return;const {error}=await db().from('messages').insert({sender_id:sessionUser.id,recipient_id:recipientId,body,message_type:'text'});if(error)toast('تعذر إرسال الرسالة: '+error.message);else{input.value='';toast('تم إرسال الرسالة الخاصة');render();}}
async function reportUser(id){if(id===sessionUser.id)return toast('لا يمكنك الإبلاغ عن نفسك');const reason=prompt('اكتب سبب الإبلاغ والمشكلة بالتفصيل');if(!reason?.trim())return;const {error}=await db().from('user_reports').insert({reporter_id:sessionUser.id,reported_id:id,reason:reason.trim()});toast(error?'تعذر إرسال البلاغ: '+error.message:'تم إرسال البلاغ إلى المطور للمراجعة');}
async function reviewReport(reportId,userId){const {error}=await db().rpc('developer_review_report',{p_report:reportId,p_action:'reviewed'});if(error)return toast('تعذر فتح البلاغ: '+error.message);window.moderationTarget=userId;location.hash='user/'+userId;}
async function devBanFromProfile(id){const choice=prompt('اكتب permanent للإغلاق النهائي، أو عدد الساعات مثل 6 للإغلاق المؤقت:');if(!choice?.trim())return;const action=choice.trim().toLowerCase()==='permanent'?'permanent':`hours:${Number(choice)}`;if(action.startsWith('hours:')&&(!Number.isInteger(Number(choice))||Number(choice)<1))return toast('أدخل عدد ساعات صحيحًا');const {error}=await db().rpc('developer_set_account_status',{p_user:id,p_action:action});toast(error?'تعذر حظر الحساب: '+error.message:action==='permanent'?'تم حظر الحساب نهائيًا':'تم حظر الحساب لمدة '+choice+' ساعة');}
async function devAccountAction(){const id=document.getElementById('dev-account-id').value.trim(),action=document.getElementById('dev-account-action').value;if(!id)return toast('أدخل UUID الحساب');const {error}=await db().rpc('developer_set_account_status',{p_user:id,p_action:action});toast(error?'تعذر تنفيذ الإجراء: '+error.message:action==='hour'?'تم إغلاق الحساب لمدة ساعة':action==='permanent'?'تم إغلاق الحساب نهائيًا':'تمت إعادة فتح الحساب');}
async function contactDeveloper(channel='WebChat'){const {data:dev}=await db().from('profiles').select('id').eq('role','developer').limit(1).maybeSingle();if(!dev)return toast('لم يتم العثور على حساب المطور');window.pendingDeveloperMessage=`مرحبًا، أريد طلب شحن رصيد عبر ${channel}.`;location.hash='dm/'+dev.id;}
async function profilePage(){const [follower,following,gifts]=await Promise.all([db().from('follows').select('id',{count:'exact',head:true}).eq('following_id',sessionUser.id),db().from('follows').select('id',{count:'exact',head:true}).eq('follower_id',sessionUser.id),db().from('user_gifts').select('id,gift_name,gift_image_url,created_at').eq('receiver_id',sessionUser.id).order('created_at',{ascending:false}).limit(20)]);return page('الملف الشخصي','profile',`<section class="profile-hero vip-profile vip-${profile.vip_level||0}" style="--vip-art:url('${vipArt(profile.vip_level)}')"><div class="vip-art-layer"></div><div class="vip-hero-image"></div><div class="vip-wings"><i></i><i></i></div><div class="profile-avatar-wrap"><img src="${profile.avatar_url||DEFAULT_AVATAR}" class="profile-avatar vip-${profile.vip_level||0}"><span class="online-ring"></span></div><div><span class="vip-label" style="color:${vip(profile.vip_level).color}">${vip(profile.vip_level).name}</span><h1>${escapeHtml(profile.display_name||profile.username)}</h1><p>@${escapeHtml(profile.username)} · ID #${profile.id.slice(0,8)}</p></div><button class="icon-btn outline" onclick="changeAvatar()"><i class="fa-solid fa-camera"></i></button></section><div class="stats"><div><b>${follower.count||0}</b><span>المتابعون</span></div><div><b>${following.count||0}</b><span>أتابعهم</span></div><div><b>—</b><span>الزوار</span></div><div><b>${fmt(profile.coins)}</b><span>كوينز</span></div></div><div class="panel charge-panel"><div class="panel-head"><h2>شحن الرصيد</h2><span class="status">تواصل مع المطور</span></div><p class="empty">اختر طريقة التواصل، وسيتم فتح حساب المطور داخل WebChat لإرسال طلب الشحن.</p><div class="contact-buttons"><button class="btn gold" onclick="contactDeveloper('WhatsApp')"><i class="fa-brands fa-whatsapp"></i> WhatsApp</button><button class="btn ghost" onclick="contactDeveloper('Instagram')"><i class="fa-brands fa-instagram"></i> Instagram</button><button class="btn ghost" onclick="contactDeveloper('Telegram')"><i class="fa-brands fa-telegram"></i> Telegram</button><button class="btn gold full" onclick="contactDeveloper('WebChat')">مراسلة المطور داخل الموقع</button></div></div><div class="profile-grid"><div class="panel"><div class="panel-head"><h2>إدارة الحساب</h2><span class="status">${profile.status==='active'?'نشط':'موقوف'}</span></div><button class="setting" onclick="changeName()"><i class="fa-solid fa-user-pen"></i><span><b>تغيير الاسم</b><small>يُحفظ في قاعدة البيانات</small></span><i class="fa-solid fa-chevron-left"></i></button><button class="setting" onclick="changePassword()"><i class="fa-solid fa-lock"></i><span><b>كلمة المرور</b><small>تحديث عبر Supabase Auth</small></span><i class="fa-solid fa-chevron-left"></i></button><a class="setting" href="app.html#vip"><i class="fa-solid fa-gem"></i><span><b>الترقية</b><small>${vip(profile.vip_level).perk}</small></span><i class="fa-solid fa-chevron-left"></i></a><button class="setting" onclick="openSupport()"><i class="fa-solid fa-headset"></i><span><b>الدعم والشحن</b><small>إرسال طلب حقيقي للمطور</small></span><i class="fa-solid fa-chevron-left"></i></button><button class="setting" onclick="convertGifts()"><i class="fa-solid fa-arrows-rotate"></i><span><b>تحويل الهدايا إلى مال</b><small>يُسجل معاملة وخصم 20%</small></span><i class="fa-solid fa-chevron-left"></i></button></div><div class="panel gifts"><div class="panel-head"><h2>الهدايا المستلمة</h2><span>${gifts.data?.length||0} هدايا</span></div><div class="gift-grid">${(gifts.data||[]).map(g=>`<div><b>🎁</b><small>${escapeHtml(g.gift_name)}</small></div>`).join('')||'<p class="empty">لا توجد هدايا مستلمة.</p>'}</div></div></div><button class="btn danger full" onclick="logout()">تسجيل الخروج</button>`);}
async function vipPage(){return page('العضوية VIP','vip',`<div class="page-title"><span class="eyebrow">ترقية محفوظة في حسابك</span><h1>مستويات VIP</h1><p>أرسل طلب الترقية للمطور، وسيتم تفعيله على ملفك الحقيقي.</p></div><div class="vip-grid">${VIPS.slice(1).map(v=>`<div class="vip-card ${profile.vip_level===v.level?'current':''}" style="--vip:${v.color}"><div class="vip-top"><span>VIP ${v.level}</span><i class="fa-solid fa-crown"></i></div><h2>${fmt(v.cost)} <small>كوينز</small></h2><p>${v.perk}</p><button class="btn ${profile.vip_level>=v.level?'ghost':'gold'} full" onclick="requestVip(${v.level})">${profile.vip_level===v.level?'مستواك الحالي':profile.vip_level>v.level?'تم فتحه':'طلب الترقية'}</button></div>`).join('')}</div>`);}
async function topPage(){const {data,error}=await db().from('profiles').select('id,username,display_name,coins,vip_level,avatar_url').order('coins',{ascending:false}).limit(20);if(error)throw error;return page('لوحة التوب','top',`<div class="page-title"><span class="eyebrow">بيانات مباشرة من Supabase</span><h1>أغنى اللاعبين</h1><p>الترتيب يتحدث من أرصدة الحسابات الفعلية.</p></div><div class="leaderboard">${(data||[]).map((x,i)=>`<div class="leader clickable-user" onclick="openUserProfile('${x.id}')"><b class="rank">${i+1}</b><img src="${x.avatar_url||DEFAULT_AVATAR}"><div><h3>${escapeHtml(x.display_name||x.username)} ${x.vip_level===5?'♛':''}</h3><small>VIP ${x.vip_level||0} · ID #${x.id.slice(0,8)} <button class="copy-id" onclick="event.stopPropagation();copyId('${x.id}')">نسخ</button></small></div><strong><i class="fa-solid fa-coins"></i> ${fmt(x.coins)}</strong></div>`).join('')||'<p class="empty">لا يوجد مستخدمون بعد.</p>'}</div>`);}
async function searchPage(){return page('البحث','search',`<div class="page-title"><span class="eyebrow">بحث مباشر في الحسابات</span><h1>البحث والاستكشاف</h1><p>ابحث باسم المستخدم أو رقم الـ ID.</p></div><div class="search-box"><i class="fa-solid fa-magnifying-glass"></i><input id="search-input" placeholder="اكتب اسمًا أو ID..." oninput="runSearch(this.value)"></div><div id="search-results"></div>`);}
async function notifications(){const [{data:notes,error},{data:followers},{data:following}]=await Promise.all([db().from('notifications').select('id,actor_id,title,body,kind,created_at,read_at').eq('user_id',sessionUser.id).order('created_at',{ascending:false}).limit(50),db().from('follows').select('follower_id').eq('following_id',sessionUser.id).limit(200),db().from('follows').select('following_id').eq('follower_id',sessionUser.id).limit(200)]);if(error)throw error;const fIds=(followers||[]).map(x=>x.follower_id),gIds=(following||[]).map(x=>x.following_id),nIds=(notes||[]).map(x=>x.actor_id).filter(Boolean),ids=[...new Set([...fIds,...gIds,...nIds])];const {data:actors}=ids.length?await db().from('profiles').select('id,display_name,username,avatar_url,vip_level').in('id',ids):{data:[]};const byId=Object.fromEntries((actors||[]).map(a=>[a.id,a]));const latest={};(notes||[]).filter(n=>n.actor_id).forEach(n=>{if(!latest[n.actor_id])latest[n.actor_id]=n;});const system=(notes||[]).filter(n=>!n.actor_id);return page('الإشعارات','notifications',`<div class="page-title"><span class="eyebrow">صندوق الوارد الاجتماعي</span><h1>الإشعارات</h1><p>كل الحسابات التي تتابعك أو تتابعها، مع رسائل WebChat وإشعارات النظام.</p></div><div class="inbox"><div class="inbox-account system-inbox"><div class="webchat-logo">W</div><div><b>WebChat</b><small>إشعارات النظام، VIP، البريد والدعم</small></div><span>${system.length}</span></div>${system.map(n=>`<div class="inbox-item system-item"><div class="system-dot">✦</div><div><b>${escapeHtml(n.title)}</b><p>${escapeHtml(n.body)}</p><small>${new Date(n.created_at).toLocaleString('ar-EG')}</small></div></div>`).join('')}${ids.map(id=>{const a=byId[id];if(!a)return '';const tags=[fIds.includes(id)?'يتابعك':'',gIds.includes(id)?'تتابعه':''].filter(Boolean).join(' · ');const n=latest[id];return `<div class="inbox-account person-inbox" onclick="openConversation('${id}')"><img class="notice-avatar vip-avatar vip-${a.vip_level||0}" src="${a.avatar_url||DEFAULT_AVATAR}"><div><b>${escapeHtml(a.display_name||a.username)}</b><small>${tags||'حساب متفاعل'}${n?' · '+escapeHtml(n.title):''}</small><em>${n?escapeHtml(n.body):'اضغط لفتح المحادثة'}</em></div><i class="fa-solid fa-chevron-left"></i></div>`;}).join('')||'<p class="empty">لا توجد حسابات بعد.</p>'}</div>`);}
async function runSearch(q){const out=document.getElementById('search-results');if(!out)return;if(!q.trim()){out.innerHTML='';return;}const {data,error}=await db().from('profiles').select('id,username,display_name,avatar_url,vip_level').or(`username.ilike.%${q}%,display_name.ilike.%${q}%`).limit(20);if(error){out.innerHTML='<p class="empty">تعذر تنفيذ البحث.</p>';return;}out.innerHTML=`<div class="search-results">${(data||[]).map(x=>`<div class="user-result"><img src="${x.avatar_url||DEFAULT_AVATAR}" onclick="openUserProfile('${x.id}')" style="cursor:pointer"><div onclick="openUserProfile('${x.id}')" style="cursor:pointer"><b>${escapeHtml(x.display_name||x.username)}</b><small>ID #${x.id.slice(0,8)} · VIP ${x.vip_level||0}</small></div><button class="btn small ghost" onclick="openUserProfile('${x.id}')">الملف</button></div>`).join('')||'<p class="empty">لا توجد نتائج.</p>'}</div>`;}
async function copyId(id){try{await navigator.clipboard.writeText(id);toast('تم نسخ UUID إلى الحافظة');}catch(e){const area=document.createElement('textarea');area.value=id;document.body.appendChild(area);area.select();document.execCommand('copy');area.remove();toast('تم نسخ UUID إلى الحافظة');}}
function openUserProfile(id){location.hash='user/'+id;}
async function followUser(id){if(id===sessionUser.id)return toast('لا يمكنك متابعة نفسك');const {error}=await db().from('follows').upsert({follower_id:sessionUser.id,following_id:id},{onConflict:'follower_id,following_id'});if(error)toast('تعذر المتابعة: '+error.message);else{await db().from('notifications').insert({user_id:id,actor_id:sessionUser.id,title:'متابع جديد',body:`${profile.display_name||profile.username} بدأ بمتابعتك`,kind:'follow'});toast('تمت المتابعة وحُفظت في قاعدة البيانات');}}
async function requestRelationship(targetId){if(targetId===sessionUser.id)return toast('لا يمكنك إنشاء علاقة مع نفسك');const {error}=await db().rpc('request_relationship',{p_target:targetId});toast(error?'تعذر إرسال طلب العلاقة: '+error.message:'تم إرسال طلب العلاقة. عند الموافقة يخصم 500 كوينز من كل طرف');}
async function acceptRelationshipFrom(actorId){const {data:r}=await db().from('relationship_requests').select('id').eq('requester_id',actorId).eq('target_id',sessionUser.id).eq('status','pending').order('created_at',{ascending:false}).limit(1).maybeSingle();if(!r)return toast('الطلب غير موجود أو تمت معالجته');return acceptRelationship(r.id);}
async function rejectRelationshipFrom(actorId){const {data:r}=await db().from('relationship_requests').select('id').eq('requester_id',actorId).eq('target_id',sessionUser.id).eq('status','pending').order('created_at',{ascending:false}).limit(1).maybeSingle();if(!r)return toast('الطلب غير موجود أو تمت معالجته');return rejectRelationship(r.id);}
async function acceptRelationship(requestId){const {error}=await db().rpc('accept_relationship',{p_request:requestId});toast(error?'تعذر قبول العلاقة: '+error.message:'تم قبول العلاقة وخصم 500 كوينز من كل طرف');render();}
async function rejectRelationship(requestId){const {error}=await db().rpc('reject_relationship',{p_request:requestId});toast(error?'تعذر رفض العلاقة: '+error.message:'تم رفض طلب العلاقة');render();}
async function queueForGame(game,bet){const box=document.getElementById('match-status');if(!box)return;box.style.display='block';let seconds=15;const rotating=['سالم','لاعب VIP','مهاجم سريع','عاشق Roulette','لاعب جديد','Shadow'];box.innerHTML=`<div class="match-queue"><div class="queue-wheel">${game==='Roulette'?'🎡':'🎮'}</div><h2>جاري البحث عن لاعبين</h2><p>اللعبة: <b>${escapeHtml(game)}</b> · الرهان: <b>${bet} كوينز</b></p><div class="queue-counter">${seconds}</div><div class="queue-players" id="queue-players"></div><small>يتغير اللاعبون المنتظرون تلقائيًا حتى اكتمال المطابقة...</small></div>`;const timer=setInterval(()=>{seconds--;const c=document.querySelector('.queue-counter');if(c)c.textContent=Math.max(seconds,0);const list=document.getElementById('queue-players');if(list)list.innerHTML=[0,1,2].map((_,i)=>`<span>● ${rotating[Math.floor(Math.random()*rotating.length)]}</span>`).join('');if(seconds<=0){clearInterval(timer);const b=document.getElementById('match-status');if(b)b.innerHTML+=`<div class="robot-offer"><p>لم نجد لاعبين كافيين الآن.</p><button class="btn gold" onclick="startRobotMatch('${game}',${bet})">هل تريد اللعب مع الـRobot؟</button></div>`;}},1000);const {data,error}=await db().rpc('join_game_match',{p_game_type:game,p_bet_amount:bet});if(error&&box)box.innerHTML+=`<p class="empty">تعذر تسجيل قائمة الانتظار: ${escapeHtml(error.message)}</p>`;else if(data?.status==='playing'&&box){clearInterval(timer);box.innerHTML=`<div class="match-queue"><div class="queue-wheel">🎉</div><h2>بدأت المباراة</h2><p>${escapeHtml(data.game_type)} · الرهان ${data.bet_amount} كوينز</p><span class="status">عدد اللاعبين: ${data.players}</span></div>`;}}
async function inspectMatch(id){const {data,error}=await db().from('game_matches').select('id,game_type,bet_amount,max_players,status,started_at').eq('id',id).single();if(error)return toast('تعذر قراءة المباراة');const {count}=await db().from('game_match_players').select('user_id',{count:'exact',head:true}).eq('match_id',id);toast(data.status==='playing'?`بدأت ${data.game_type} مع ${count} لاعبين`:`ما زلنا نبحث عن لاعبين (${count}/${data.max_players})`);}
async function joinRoom(id){const {data,error}=await db().rpc('join_room',{p_room_id:id});if(error){toast('تعذر الانضمام للغرفة: '+error.message);return;}const msg=await db().from('messages').insert({room_id:id,sender_id:sessionUser.id,body:`${vip(profile.vip_level).level?`✨ ${profile.display_name||profile.username} دخل بإطلالة ${vip(profile.vip_level).name} 👑`:`${profile.display_name||profile.username} انضم إلى الغرفة`}`,message_type:profile.vip_level?'vip_entry':'system'});if(msg.error)toast('تم الانضمام لكن تعذر تسجيل رسالة الدخول: '+msg.error.message);location.hash='room/'+id;}
async function createGameRoom(game,bet){const {data,error}=await db().from('rooms').insert({owner_id:sessionUser.id,name:`غرفة ${game} · ${profile.display_name}`,room_type:'game',game_type:game,bet_amount:bet,cover_emoji:game==='Ludo'?'🎲':'🎡'}).select('id').single();if(error)toast('تعذر إنشاء الغرفة: '+error.message);else{await db().from('room_members').insert({room_id:data.id,user_id:sessionUser.id});toast('تم إنشاء غرفة حقيقية');location.hash='gathering';}}
async function createGathering(){const name=prompt('اكتب اسم الغرفة');if(!name?.trim())return;const {data,error}=await db().from('rooms').insert({owner_id:sessionUser.id,name:name.trim(),room_type:'gathering',cover_emoji:'✨'}).select('id').single();if(error)toast('تعذر إنشاء الغرفة: '+error.message);else{await db().from('room_members').insert({room_id:data.id,user_id:sessionUser.id});toast('تم إنشاء الغرفة وحفظها');location.hash='gathering';}}
async function changeName(){const n=prompt('الاسم الجديد',profile.display_name||profile.username);if(!n?.trim())return;const {error}=await db().from('profiles').update({display_name:n.trim(),username:n.trim(),updated_at:new Date().toISOString()}).eq('id',sessionUser.id);if(error)toast('تعذر تحديث الاسم: '+error.message);else{await db().auth.updateUser({data:{full_name:n.trim()}});profile=await getProfile();toast('تم تحديث الاسم في قاعدة البيانات');render();}}
async function changeAvatar(){const n=prompt('رابط الصورة المباشر',profile.avatar_url||DEFAULT_AVATAR);if(!n?.trim())return;const {error}=await db().from('profiles').update({avatar_url:n.trim(),updated_at:new Date().toISOString()}).eq('id',sessionUser.id);if(error)toast('تعذر تحديث الصورة: '+error.message);else{profile.avatar_url=n.trim();toast('تم تحديث الصورة');render();}}
async function changePassword(){const n=prompt('كلمة المرور الجديدة (6 أحرف على الأقل)');if(!n||n.length<6)return toast('كلمة المرور يجب أن تكون 6 أحرف على الأقل');const {error}=await db().auth.updateUser({password:n});toast(error?'تعذر تغيير كلمة المرور: '+error.message:'تم تغيير كلمة المرور عبر Supabase Auth');}
async function requestVip(level){const {error}=await db().from('support_tickets').insert({user_id:sessionUser.id,subject:`طلب ترقية VIP ${level}`,description:`أطلب تفعيل VIP ${level} للحساب ${profile.id}`,status:'pending'});toast(error?'تعذر إرسال الطلب: '+error.message:'تم إرسال طلب VIP للمطور وحُفظ في قاعدة البيانات');}
async function openSupport(){const text=prompt('اكتب طلب الشحن أو المشكلة');if(!text?.trim())return;const {error}=await db().from('support_tickets').insert({user_id:sessionUser.id,subject:'طلب دعم وشحن',description:text.trim(),status:'pending'});toast(error?'تعذر إرسال الطلب: '+error.message:'تم إرسال الطلب للمطور');}
async function convertGifts(){const {data:gifts,error}=await db().from('user_gifts').select('id').eq('receiver_id',sessionUser.id).limit(100);if(error)return toast('تعذر قراءة الهدايا');if(!gifts?.length)return toast('لا توجد هدايا للتحويل');const value=gifts.length*250,fee=value*.2,net=value-fee;const {error:txError}=await db().from('gift_conversions').insert({user_id:sessionUser.id,gift_value:value,fee,net_value:net});if(txError)return toast('تعذر تسجيل المعاملة: '+txError.message);toast('تم تسجيل طلب التحويل بعد خصم 20%');}
function mailToReset(t){const code=(t.description.match(/رمز التحقق:\s*([0-9]{6})/)||[])[1]||'';const email=(t.description.match(/البريد:\s*([^\s—]+)/)||[])[1]||'';const subject=encodeURIComponent('رمز إعادة تعيين كلمة المرور');const body=encodeURIComponent(`مرحبًا،

رمز التحقق الخاص بك هو: ${code}

هذا الرمز صالح لمدة 15 دقيقة. بعد التحقق منه استخدم رابط إعادة تعيين كلمة المرور الآمن.`);return `mailto:${email}?subject=${subject}&body=${body}`;}
async function developerPage(){if(profile.role!=='developer')return page('غير مصرح','home',`<div class="panel"><h2>غير مصرح</h2><p class="empty">هذه الصفحة متاحة لحسابات المطور فقط.</p></div>`);const {data: tickets}=await db().from('support_tickets').select('id,user_id,subject,description,status,created_at').eq('status','pending').order('created_at',{ascending:false}).limit(50);const {data: reports}=await db().from('user_reports').select('id,reporter_id,reported_id,reason,created_at').eq('status','pending').order('created_at',{ascending:false}).limit(50);return page('لوحة المطور','home',`<div class="page-title"><span class="eyebrow">Developer control center</span><h1>لوحة المطور</h1><p>هذه العمليات تُكتب مباشرة في قاعدة البيانات الحقيقية.</p></div><div class="dev-grid"><div class="panel"><div class="panel-head"><h2>شحن رصيد</h2><span class="status">صلاحية المطور</span></div><div class="field dev-field"><label>معرّف المستخدم UUID <span class="hint">انسخه من ملف الحساب</span></label><input id="dev-id" placeholder="الصق UUID هنا"></div><div class="field dev-field"><label>الرصيد الجديد</label><input id="dev-coins" type="number"></div><button class="btn gold full" onclick="devRecharge()">حفظ الرصيد</button></div><div class="panel"><div class="panel-head"><h2>تفعيل VIP</h2><span class="status">صلاحية المطور</span></div><div class="field dev-field"><label>معرّف المستخدم UUID <span class="hint">انسخه من ملف الحساب</span></label><input id="dev-vip-id" placeholder="الصق UUID هنا"></div><div class="field dev-field"><label>المستوى</label><select id="dev-level"><option value="1">VIP 1</option><option value="2">VIP 2</option><option value="3">VIP 3</option><option value="4">VIP 4</option><option value="5">VIP 5</option></select></div><button class="btn gold full" onclick="devVip()">حفظ الترقية</button></div></div><div class="panel moderation-panel" style="margin-top:15px"><div class="panel-head"><h2>إدارة الحسابات</h2><span class="status">بالـ UUID</span></div><div class="field dev-field"><label>UUID الحساب</label><input id="dev-account-id" placeholder="الصق ID الحساب"></div><div class="field dev-field"><label>الإجراء</label><select id="dev-account-action"><option value="hour">إغلاق مؤقت لمدة ساعة</option><option value="permanent">إغلاق نهائي</option><option value="restore">إعادة فتح الحساب</option></select></div><button class="btn danger full" onclick="devAccountAction()">تنفيذ الإجراء</button></div><div class="panel reports-panel" style="margin-top:15px"><div class="panel-head"><h2>بلاغات المستخدمين</h2><span>${reports?.length||0}</span></div>${(reports||[]).map(r=>`<div class="notice"><div><b>بلاغ عن حساب</b><p>${escapeHtml(r.reason)}</p><small>المبلّغ: ${r.reporter_id} · الحساب: ${r.reported_id}</small></div><span style="display:flex;gap:6px"><button class="btn small gold" onclick="reviewReport('${r.id}','${r.reported_id}')">مراجعة</button><button class="btn small ghost" onclick="reviewReport('${r.id}','dismissed')">تجاهل</button></span></div>`).join('')||'<p class="empty">لا توجد بلاغات معلقة.</p>'}</div><div class="panel broadcast-panel" style="margin-top:15px"><div class="panel-head"><h2>إشعار جماعي</h2><span class="status">يصل لجميع الحسابات</span></div><div class="field dev-field"><label>عنوان الإشعار</label><input id="broadcast-title" placeholder="رسالة من WebChat"></div><div class="field dev-field"><label>نص الإشعار</label><textarea id="broadcast-body" placeholder="اكتب الإعلان أو التنبيه هنا"></textarea></div><button class="btn gold full" onclick="devBroadcast()">إرسال إلى جميع المستخدمين</button></div><div class="panel" style="margin-top:15px"><div class="panel-head"><h2>البلاغات وطلبات الدعم</h2><span>${tickets?.length||0}</span></div>${(tickets||[]).map(t=>`<div class="notice"><div><b>${escapeHtml(t.subject)}</b><p>${escapeHtml(t.description)}</p><small>${t.user_id} · ${t.status}</small></div>${t.subject.startsWith('طلب ترقية VIP')?`<span style="display:flex;gap:6px"><button class="btn small gold" onclick="approveVip('${t.id}','${t.user_id}')">ترقية</button><button class="btn small danger" onclick="rejectVip('${t.id}','${t.user_id}')">رفض</button></span>`:t.subject.startsWith('طلب إعادة تعيين')?`<span style="display:flex;gap:6px"><a class="btn small gold" href="${mailToReset(t)}" target="_blank">فتح البريد الجاهز</a><button class="btn small ghost" onclick="approvePasswordReset('${t.id}','${t.user_id}')">إرسال رابط آمن</button></span>`:`<button class="btn small ghost" onclick="closeTicket('${t.id}')">إغلاق</button>`}</div>`).join('')||'<p class="empty">لا توجد طلبات.</p>'}</div><div class="panel" style="margin-top:15px"><div class="panel-head"><h2>إنشاء هدية جديدة</h2><span class="status">تظهر للمستخدمين</span></div><div class="dev-grid"><div class="field dev-field"><label>اسم الهدية</label><input id="gift-name" placeholder="تاج ملكي"></div><div class="field dev-field"><label>الإيموجي</label><input id="gift-emoji" placeholder="👑"></div><div class="field dev-field"><label>السعر بالكوينز</label><input id="gift-price" type="number" placeholder="100"></div><div class="field dev-field"><label>رابط الصورة اختياري</label><input id="gift-image" placeholder="https://..."></div></div><button class="btn gold full" onclick="devCreateGift()">إضافة الهدية</button></div>`);}
async function devBroadcast(){const title=document.getElementById('broadcast-title')?.value.trim(),body=document.getElementById('broadcast-body')?.value.trim();if(!title||!body)return toast('اكتب عنوان الإشعار ونصه');const {data,error}=await db().rpc('broadcast_notification',{p_title:title,p_body:body,p_kind:'system'});toast(error?'تعذر الإرسال: '+error.message:`تم إرسال الإشعار إلى ${data||0} مستخدم`);if(!error){document.getElementById('broadcast-title').value='';document.getElementById('broadcast-body').value='';}}
async function devCreateGift(){const name=document.getElementById('gift-name').value.trim(),emoji=document.getElementById('gift-emoji').value.trim()||'🎁',price=Number(document.getElementById('gift-price').value),image=document.getElementById('gift-image').value.trim()||null;if(!name||!Number.isFinite(price)||price<0)return toast('أدخل اسمًا وسعرًا صحيحًا');const {error}=await db().from('gift_catalog').insert({name,emoji,price,image_url:image,created_by:sessionUser.id});toast(error?'تعذر إضافة الهدية: '+error.message:'تمت إضافة الهدية وأصبحت متاحة للمستخدمين');render();}
async function devRecharge(){const id=document.getElementById('dev-id').value.trim(),coins=Number(document.getElementById('dev-coins').value);if(!id||!Number.isFinite(coins)||coins<0)return toast('أدخل UUID ورصيدًا صحيحًا');const {error}=await db().rpc('developer_set_coins',{p_user:id,p_coins:coins});toast(error?'تعذر شحن الرصيد: '+error.message:'تم شحن الرصيد وحفظه في قاعدة البيانات');}
async function devVip(){const id=document.getElementById('dev-vip-id').value.trim(),level=Number(document.getElementById('dev-level').value);if(!id||!Number.isInteger(level)||level<0||level>5)return toast('أدخل UUID ومستوى VIP صحيحًا');const {error}=await db().rpc('developer_set_vip',{p_user:id,p_level:level});toast(error?'تعذر تفعيل VIP: '+error.message:'تم تفعيل VIP وحفظه في قاعدة البيانات');}
async function approvePasswordReset(ticketId,userId){const {data:p}=await db().from('profiles').select('email').eq('id',userId).single();if(!p?.email)return toast('لا يوجد بريد مرتبط بالحساب');const sent=await db().auth.resetPasswordForEmail(p.email,{redirectTo:location.origin+'/index.html'});if(sent.error)return toast('تعذر إرسال رابط الاستعادة: '+sent.error.message);await db().from('support_tickets').update({status:'approved'}).eq('id',ticketId);await db().from('notifications').insert({user_id:userId,title:'تم اعتماد إعادة التعيين',body:'أرسل المطور رابطًا آمنًا إلى بريدك الإلكتروني لتعيين كلمة مرور جديدة','kind':'password_reset'});toast('تم إرسال رابط إعادة التعيين الآمن إلى بريد المستخدم');render();}
async function closeTicket(id){const {error}=await db().from('support_tickets').update({status:'closed'}).eq('id',id);toast(error?'تعذر تحديث البلاغ: '+error.message:'تم إغلاق البلاغ');render();}
async function approveVip(ticketId,userId){const {data:t,error}=await db().from('support_tickets').select('subject').eq('id',ticketId).eq('status','pending').single();if(error)return toast('الطلب غير موجود أو تمت معالجته');const m=t.subject.match(/VIP\s*(\d+)/i),level=m?Number(m[1]):1;const result=await db().rpc('developer_decide_vip',{p_ticket:ticketId,p_user:userId,p_level:level,p_accept:true});if(result.error)return toast('تعذر اعتماد الترقية: '+result.error.message);toast('تمت ترقية المستخدم واختفى الطلب من القائمة');render();}
async function rejectVip(ticketId,userId){const result=await db().rpc('developer_decide_vip',{p_ticket:ticketId,p_user:userId,p_level:0,p_accept:false});if(result.error)return toast('تعذر رفض الطلب: '+result.error.message);toast('تم رفض الطلب واختفاؤه من القائمة');render();}

async function sendRoomMessage(roomId){const input=document.getElementById('room-message-input'),body=input?.value.trim();if(!body)return;const {error}=await db().from('messages').insert({room_id:roomId,sender_id:sessionUser.id,body,message_type:'text'});if(error)toast('تعذر إرسال الرسالة: '+error.message);else{input.value='';render();}}
async function roomPage(id){await db().rpc('touch_room_presence',{p_room:id});const [{data:room,error},{data:msgs},{data:members}]=await Promise.all([db().from('rooms').select('id,name,room_type,game_type,cover_emoji').eq('id',id).single(),db().from('messages').select('id,sender_id,body,created_at,message_type').eq('room_id',id).order('created_at',{ascending:true}).limit(100),db().from('room_members').select('user_id').eq('room_id',id).limit(100)]);if(error||!room)return page('الغرفة','gathering',`<div class="panel"><h2>الغرفة غير موجودة</h2></div>`);const ids=[...new Set((members||[]).map(x=>x.user_id).concat((msgs||[]).map(x=>x.sender_id)))];const {data:people}=ids.length?await db().from('profiles').select('id,display_name,username,avatar_url,vip_level').in('id',ids):{data:[]};const byId=Object.fromEntries((people||[]).map(x=>[x.id,x]));return page(room.name,'gathering',`<div class="room-page"><div class="room-head"><button class="btn ghost" onclick="location.hash='gathering'">العودة</button><button class="btn danger small" onclick="leaveRoom('${id}')">مغادرة الغرفة</button><div><span class="eyebrow">${room.room_type==='game'?'غرفة لعبة':'تجمع ممتع · دردشة كتابية'}</span><h1>${escapeHtml(room.cover_emoji||'✨')} ${escapeHtml(room.name)}</h1></div><div class="room-tools"><button class="btn gold small" onclick="showGiftPicker('${id}')">🎁 الهدايا</button><button class="btn ghost small" onclick="toggleVoiceRecorder('${id}')">🎙️ رسالة صوتية</button></div></div><div class="room-layout"><div class="panel room-chat"><div class="chat-messages">${(msgs||[]).map(m=>{const u=byId[m.sender_id]||{};return `<div class="room-message ${m.message_type==='vip_entry'?'vip-entry-message':''}" onclick="openUserProfile('${m.sender_id}')"><img class="room-avatar vip-avatar vip-${u.vip_level||0}" src="${u.avatar_url||DEFAULT_AVATAR}"><div><b class="animated-vip-name vip-${u.vip_level||0}">${escapeHtml(u.display_name||u.username||'مستخدم')}</b><small>${new Date(m.created_at).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'})}</small><p>${roomMessageContent(m)}</p></div></div>`;}).join('')||'<p class="empty">لا توجد رسائل بعد.</p>'}</div><div class="room-compose"><input id="room-message-input" placeholder="اكتب رسالة في الغرفة..." onkeydown="if(event.key==='Enter')sendRoomMessage('${id}')"><button class="btn gold" onclick="sendRoomMessage('${id}')">إرسال</button></div></div><aside class="panel room-members"><div class="panel-head"><h2>الحسابات في الغرفة</h2><span>${ids.length}</span></div>${(people||[]).map(u=>`<div class="room-member" onclick="openUserProfile('${u.id}')"><img class="room-avatar vip-avatar vip-${u.vip_level||0}" src="${u.avatar_url||DEFAULT_AVATAR}"><div><b>${escapeHtml(u.display_name||u.username)}</b><small>VIP ${u.vip_level||0} · ${u.id.slice(0,8)}</small></div><button class="copy-id" onclick="event.stopPropagation();copyId('${u.id}')">نسخ</button><i class="fa-solid fa-chevron-left"></i></div>`).join('')||'<p class="empty">لا يوجد أعضاء بعد.</p>'}</aside></div></div>`);}
let robotGameState=null;
function initRobotGame(game,bet){robotGameState={game,bet,turn:0,dice:null,pendingMove:null,players:[{name:'أنت',emoji:'🧑',pieces:[0,0,0,0],pos:0,color:'#67e8f9',human:true},{name:'Robot 1',emoji:'🤖',pieces:[0],pos:0,color:'#fb7185'},{name:'Robot 2',emoji:'🤖',pieces:[0],pos:0,color:'#a5b4fc'},{name:'Robot 3',emoji:'🤖',pieces:[0],pos:0,color:'#f7c948'},{name:'Robot 4',emoji:'🤖',pieces:[0],pos:0,color:'#86efac'}],winner:null};}
function robotRoll(){const s=robotGameState;if(!s||s.winner||s.turn!==0||s.pendingMove)return;const d=1+Math.floor(Math.random()*6);s.dice=d;if(s.game==='Ludo'){s.pendingMove=d;return renderRobotGame();}s.players[0].pos+=d;if(s.players[0].pos>=40)s.winner=s.players[0].name;s.turn=1;renderRobotGame();setTimeout(robotTurn,700);}
function moveHumanPiece(index){const s=robotGameState;if(!s||s.game!=='Ludo'||s.turn!==0||!s.pendingMove)return;const p=s.players[0];p.pieces[index]+=s.pendingMove;p.pos=Math.max(...p.pieces);if(p.pieces[index]>=40)s.winner=p.name;s.pendingMove=null;s.turn=s.winner?0:1;renderRobotGame();if(!s.winner)setTimeout(robotTurn,700);}
function robotTurn(){const s=robotGameState;if(!s||s.winner)return;const p=s.players[s.turn],d=1+Math.floor(Math.random()*6);s.dice=d;if(s.game==='Ludo'){const index=Math.floor(Math.random()*p.pieces.length);p.pieces[index]+=d;p.pos=Math.max(...p.pieces);if(p.pieces[index]>=40)s.winner=p.name;}else{p.pos+=d;if(p.pos>=40)s.winner=p.name;}s.turn=s.winner?0:(s.turn+1)%s.players.length;renderRobotGame();if(!s.winner&&s.turn!==0)setTimeout(robotTurn,700);}
function renderRobotGame(){const root=document.getElementById('robot-game-root');if(!root)return;const s=robotGameState;const board=Array.from({length:52},(_,i)=>{const tokens=[];s.players.forEach((p,pi)=>p.pieces.forEach((pos,si)=>{if(pos===i+1||(pos===0&&i===0))tokens.push(`<button class="ludo-token ${p.human&&s.pendingMove?'movable':''}" style="background:${p.color}" onclick="${p.human?'moveHumanPiece('+si+')':'return false'}" title="${p.name}">${p.emoji}</button>`)}));return `<div class="ludo-cell">${tokens.join('')}</div>`}).join('');const human=s.players[0];root.innerHTML=`<div class="game-topbar"><div><span class="eyebrow">مباراة Robot · تم خصم ${s.bet} كوينز</span><h1>${escapeHtml(s.game==='Ludo'?'Ludo Royale':s.game)}</h1></div><button class="btn ghost" onclick="location.hash='games'">الخروج</button></div><div class="robot-match-banner"><span>🤖</span><div><b>مباراة فعلية ضد 4 Robots</b><small>نسبة فوزك المحددة في هذه المباراة 30% · الرهان مدفوع</small></div><span class="status">${s.winner?'انتهت المباراة':s.turn===0?'دورك':'دور الروبوت'}</span></div>${s.game==='Ludo'?`<div class="ludo-layout"><div class="ludo-board real-ludo-board">${board}</div><aside class="panel ludo-side"><h2>اللاعبون والأحجار</h2>${s.players.map((p,i)=>`<div class="robot-player ${s.turn===i&&!s.winner?'active':''}"><span style="background:${p.color}">${p.emoji}</span><div><b>${p.name}</b><small>التقدم: ${p.pos}/40 · الأحجار: ${p.pieces.length}</small></div></div>`).join('')}<div class="dice-box">${s.dice||'—'}</div>${s.winner?`<h3 class="winner-text">الفائز: ${s.winner}</h3>`:s.pendingMove?`<p class="turn-hint">ظهرت ${s.pendingMove}. اضغط على الحجر الذي تريد تحريكه.</p>`:`<button class="btn gold full" onclick="robotRoll()" ${s.turn!==0?'disabled':''}>${s.turn===0?'ارمِ النرد':'انتظر دور الـRobot'}</button>`}<p class="empty">ارمِ النرد ثم اختر حجرًا مضيئًا على المسار لتحريكه.</p></aside></div>`:`<div class="panel generic-game"><div class="generic-arena">${s.players.map(p=>`<div class="arena-player" style="left:${Math.min(p.pos*2,90)}%;border-color:${p.color}"><span>${p.emoji}</span><b>${p.name}</b></div>`).join('')}</div><div class="generic-controls">${s.winner?`<h2>الفائز: ${s.winner}</h2>`:`<button class="btn gold" onclick="robotRoll()" ${s.turn!==0?'disabled':''}>${s.turn===0?'ابدأ الجولة':'الروبوت يلعب الآن'}</button>`}<p>المباراة بدأت بعد خصم الرهان: ${escapeHtml(s.game)} ضد Robots.</p></div></div>`}`;}
async function robotGamePage(game,bet){initRobotGame(decodeURIComponent(game),Number(bet));return `<main class="robot-game-shell"><div id="robot-game-root"></div></main>`;}
async function render(){const ok=await requireAuth();if(!ok)return;const route=location.hash.slice(1)||'home';const map={home,games,gathering,profile:profilePage,vip:vipPage,top:topPage,search:searchPage,notifications,developer:developerPage};const view=route.startsWith('robot/')?()=>robotGamePage(...route.slice(6).split('/')):route.startsWith('room/')?()=>roomPage(route.slice(5)):route.startsWith('user/')?()=>userPage(route.slice(5)):route.startsWith('dm/')?()=>conversationPage(route.slice(3)):(map[route]||home);try{document.body.innerHTML=await view();if(route.startsWith('robot/'))renderRobotGame();document.title='WebChat · '+route;}catch(e){console.error(e);document.body.innerHTML=`<main class="page-content"><div class="panel"><h2>تعذر تحميل الصفحة</h2><p class="empty">${escapeHtml(e.message)}</p></div></main>`;}}
if(location.pathname.endsWith('app.html')){addEventListener('hashchange',render);addEventListener('DOMContentLoaded',render);}
